// A database where everyone can access the photos from the wedding and upload their own
// They will have to verify by using the email used when registering for the wedding!


// Info required to verify access (then give them session access because they wont want to login multiple times)
// Name
// Email
// Pin code from email!


import React from 'react';
export default function EventPhotos() { 
    return (
        <div style={styles.page}>
            {/* <h1 style={styles.heading}>Event Photos</h1>
            <p style={styles.description}>This page is under construction. Please check back after the wedding for photos from the event!</p> */}
            <h1 style={styles.heading}>Event Photos</h1>
            <p style={styles.description}>This page is currently being set up to allow guests to view and upload photos from the wedding. We want to make sure everyone can share their memories from the day! Please check back after the wedding for access to the photo gallery.</p>
            <hr></hr>
            <p style={styles.description}>In the meantime, if you have any photos you'd like to share, please email them to us at <a href="mailto:wedding@couple.com">wedding@couple.com</a>.</p>
        </div>

    );

}


const styles = {
    page: {
        background: "#faf9f7",
        minHeight: "100vh",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        fontFamily: "Georgia, 'Times New Roman', serif",
        padding: "2rem",
    },
    heading: {
        fontSize: "clamp(28px, 6vw, 48px)",
        fontWeight: 300,
        color: "#2C2C2A",
        margin: "0 0 1rem",
        lineHeight: 1.2,
    },
    description: {
        fontSize: 16,
        color: "#5F5E5A",
        maxWidth: 600,
        textAlign: "center",
    },
}
